function undo(){closeBevel();clearCutOutline();if(tool==='bevel-edge')setTool('select');if(!history.length)return;future.push(snapshot());restore(history.pop());updateUndo();persist()}
function redo(){closeBevel();clearCutOutline();if(tool==='bevel-edge')setTool('select');if(!future.length)return;history.push(snapshot());restore(future.pop());updateUndo();persist()}
