function setOpacity(material,value){material.opacity=value;material.transparent=value<1;material.depthWrite=value>=1;material.needsUpdate=true}
function addBox(x,z,w,d,h=1.8,name,type='box',meshData){
  const mesh=new THREE.Mesh(type==='mesh'?geometryFromPositions(meshData):createPrimitiveGeometry(type),new THREE.MeshStandardMaterial({color:0xa9adb2,roughness:.8}));
  mesh.castShadow=true;mesh.receiveShadow=true;mesh.material.wireframe=wireframe;mesh.position.set(x,h/2,z);mesh.scale.set(w,h,d);mesh.userData.type=type;if(type==='mesh')mesh.userData.geometry=meshData;mesh.userData.name=name||`${PRIMITIVES[type]?.label||'Malha'} ${String(++serial).padStart(2,'0')}`;
  if(type==='box'){const edges=new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry),new THREE.LineBasicMaterial({color:0x414448}));mesh.add(edges)}
  scene.add(mesh);objects.push(mesh);select(mesh);return mesh;
}
