document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool)); document.querySelector('#add-rect').onclick=()=>setTool('rectangle'); document.querySelector('#learn').onclick=()=>setTool('rectangle'); document.querySelector('.help').onclick=document.querySelector('#help-tool').onclick=()=>alert('Atalhos: V selecionar, G mover, R desenhar, E extrudar, F enquadrar, Shift+A adicionar, Shift+D duplicar. Orbite com botão central ou direito; use Shift para panorâmica e a roda para zoom. No celular, selecione Orbitar e arraste com um dedo; use dois dedos para zoom e panorâmica.');
function syncGizmo(){const modes={'gizmo-move':'translate','gizmo-rotate':'rotate','gizmo-scale':'scale'};const mode=modes[tool];transform.enabled=Boolean(mode);if(lightSelected&&mode==='translate'){transform.setMode(mode);transform.attach(light)}else if(mode&&selected&&selected.visible){transform.setMode(mode);transform.attach(selected)}else transform.detach()}
transform.addEventListener('dragging-changed',e=>{controls.enabled=!e.value});
transform.addEventListener('mouseDown',()=>{transformBefore=snapshot()});
transform.addEventListener('objectChange',()=>{if(lightSelected){for(const axis of ['x','y','z'])light.position[axis]=THREE.MathUtils.clamp(light.position[axis],-10000,10000);return}if(!selected)return;for(const axis of ['x','y','z'])selected.scale[axis]=Math.max(.0001,Math.min(10000,selected.scale[axis]));renderPanel()});
transform.addEventListener('mouseUp',()=>{if(!transformBefore)return;const before=transformBefore;transformBefore=null;if(JSON.stringify(before)!==JSON.stringify(snapshot())){history.push(before);if(history.length>50)history.shift();future=[];updateUndo();persist()}renderPanel()});
function applySnap(){transform.setTranslationSnap(snap?snapStep:null);transform.setRotationSnap(snap?Math.PI/12:null);transform.setScaleSnap(snap?snapStep:null)}
function quantize(value){return snap?Math.round(value/snapStep)*snapStep:value}
document.querySelector('#snap-step').onchange=e=>{const value=toMetres(Number(e.target.value),projectUnit);if(Number.isFinite(value)&&value>=.000001&&value<=100){snapStep=value;applySnap()}else e.target.value=formatLength(snapStep,projectUnit)};
document.querySelector('#project-name').onchange=e=>{const name=e.target.value.trim();if(!name||name===projectName){e.target.value=projectName;return}remember();projectName=name;persist()};
document.querySelector('#scene-search').oninput=renderPanel;
document.querySelector('#show-all').onclick=()=>{if(objects.every(o=>o.visible))return;remember();objects.forEach(o=>o.visible=true);renderPanel();persist()};
document.querySelector('#grid-toggle').onclick=()=>{grid.visible=!grid.visible;axisX.visible=axisZ.visible=grid.visible;document.querySelector('#grid-toggle').setAttribute('aria-pressed',String(grid.visible))};
document.querySelector('#wire-toggle').onclick=()=>{wireframe=!wireframe;objects.forEach(o=>o.material.wireframe=wireframe);document.querySelector('#wire-toggle').setAttribute('aria-pressed',String(wireframe))};
document.querySelector('#snap').onclick=()=>{snap=!snap;applySnap();const b=document.querySelector('#snap');b.classList.toggle('active',snap);b.setAttribute('aria-pressed',String(snap))};
function meshBudget(additional){return objects.reduce((sum,o)=>sum+(o.userData.geometry?.length||0),0)+additional<=MAX_SCENE_MESH_VALUES}
function duplicate(){if(!selected)return;if(objects.length>=1000){alert('A cena suporta até 1000 objetos.');return}if(!meshBudget(selected.userData.geometry?.length||0)){alert('Limite de geometria importada atingido.');return}remember();const original=selected;const copy=addBox(original.position.x+0.5,original.position.z+0.5,original.scale.x,original.scale.z,original.scale.y,undefined,original.userData.type,original.userData.geometry);copy.position.y=original.position.y;copy.rotation.copy(original.rotation);copy.material.color.copy(original.material.color);copy.material.roughness=original.material.roughness;copy.material.metalness=original.material.metalness;setOpacity(copy.material,original.material.opacity);renderPanel();persist()}
document.querySelector('#duplicate-top').onclick=duplicate;
function copyObject(){if(!selected)return false;clipboard=structuredClone(snapshot().objects[objects.indexOf(selected)]);document.querySelector('#status-text').textContent=`${selected.userData.name} copiado`;return true}
function pasteObject(){if(!clipboard)return;if(objects.length>=1000){alert('A cena suporta até 1000 objetos.');return}if(!meshBudget(clipboard.geometry?.length||0)){alert('Limite de geometria importada atingido.');return}remember();const o=clipboard;const mesh=addBox(o.position[0]+.5,o.position[2]+.5,o.scale[0],o.scale[2],o.scale[1],undefined,o.type||'box',o.geometry);mesh.userData.name=(o.name+' cópia').slice(0,100);mesh.position.y=o.position[1];mesh.rotation.set(o.rotationX||0,o.rotation||0,o.rotationZ||0);mesh.material.color.set('#'+o.color);mesh.material.roughness=o.roughness??.8;mesh.material.metalness=o.metalness??0;setOpacity(mesh.material,o.opacity??1);renderPanel();persist()}
