document.querySelector('#copy-object').onclick=copyObject;document.querySelector('#paste-object').onclick=pasteObject;document.querySelector('#cut-object').onclick=cutObject;
function copyMaterial(){if(!selected)return;const m=selected.material;materialClipboard={color:m.color.getHex(),roughness:m.roughness,metalness:m.metalness,opacity:m.opacity};renderPanel();document.querySelector('#status-text').textContent='Material copiado nesta sessão'}
