document.querySelector('#project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('Arquivo muito grande');const data=JSON.parse(await file.text());const before=snapshot();restore(data);history.push(before);if(history.length>50)history.shift();future=[];updateUndo();persist()}catch(err){alert('Não foi possível abrir o projeto: '+err.message)}finally{e.target.value=''}};
