meshFile.onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('O arquivo não pode ultrapassar 2 MB.');const lower=file.name.toLowerCase();let models;if(lower.endsWith('.stl'))models=parseSTL(await file.arrayBuffer());else if(lower.endsWith('.obj'))models=parseOBJ(await file.text());else throw new Error('Escolha um arquivo STL ou OBJ.');const size=models.reduce((n,m)=>n+m.geometry.length,0);if(objects.length+models.length>1000||!meshBudget(size))throw new Error('A importação excede o limite de geometria da cena.');const before=snapshot(),name=file.name.replace(/\.(stl|obj)$/i,'').trim().slice(0,90)||'Malha';try{for(const [i,m] of models.entries()){const mesh=addBox(m.position[0],m.position[2],m.scale[0],m.scale[2],m.scale[1],models.length>1?`${name} ${i+1}`:name,'mesh',m.geometry);mesh.position.y=m.position[1]}history.push(before);if(history.length>50)history.shift();future=[];updateUndo();renderPanel();persist();document.querySelector('#status-text').textContent=`${models.length} malha(s) importada(s)`}catch(err){restore(before);throw err}}catch(err){alert('Não foi possível importar: '+err.message)}finally{e.target.value=''}};
function exportGroup(){const group=new THREE.Group();objects.filter(o=>o.visible).forEach(o=>{const mesh=new THREE.Mesh(o.geometry,o.material.clone());mesh.material.emissive.setHex(0);mesh.material.wireframe=false;mesh.name=o.userData.name;mesh.position.copy(o.position);mesh.rotation.copy(o.rotation);mesh.scale.copy(o.scale);group.add(mesh)});group.updateMatrixWorld(true);return group}
function withExportGroup(action){const group=exportGroup();if(!group.children.length){alert('Não há objetos visíveis para exportar.');return}try{action(group)}catch(err){alert('Falha ao exportar: '+err.message);group.children.forEach(o=>o.material.dispose())}}
function disposeExport(group){group.children.forEach(o=>o.material.dispose())}
document.querySelector('#export-glb').onclick=()=>{dropdown.hidden=true;withExportGroup(group=>new GLTFExporter().parse(group,result=>{download(result,projectFilename('glb'),'model/gltf-binary');disposeExport(group)},err=>{disposeExport(group);alert('Falha ao exportar: '+err.message)},{binary:true}))};
