document.querySelector('#export-png').onclick=()=>{dropdown.hidden=true;renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(blob)download(blob,'bender-captura.png','image/png');else alert('Não foi possível capturar a imagem')},'image/png')};
function point(e){const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height)*2+1);raycaster.setFromCamera(mouse,camera);return raycaster.ray.intersectPlane(plane,new THREE.Vector3())}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0||tool==='orbit'||start||transform.dragging)return;point(e);if(tool==='bevel-edge'){pickBevelEdge(e);return}if(tool==='measure'){const p=point(e);if(!p)return;p.x=quantize(p.x);p.z=quantize(p.z);if(!measureStart||measureComplete){measureStart=p;measureComplete=false;updateMeasurement(p)}else{updateMeasurement(p);measureComplete=true}return}if((tool==='select'||tool.startsWith('gizmo-'))&&lightMarker.visible){const bulb=raycaster.intersectObject(lightMarker,false)[0];const nearest=raycaster.intersectObjects(objects.filter(o=>o.visible),false)[0];if(bulb&&(!nearest||bulb.distance<nearest.distance)){selectLight();return}}if(tool.startsWith('gizmo-')){const hits=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked),false);select(hits[0]?.object||null)}else if(tool==='select'){const hits=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked),false);select(hits[0]?.object||null)}else if(tool==='move'){const hits=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked),false);if(!hits[0])return;select(hits[0].object);const p=point(e);if(!p)return;start={p,before:snapshot(),x:selected.position.x,z:selected.position.z,pointer:e.pointerId};renderer.domElement.setPointerCapture(e.pointerId)}else if(tool==='face'){const hit=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked),false)[0];if(!hit||hit.object.userData.type!=='box')return;select(hit.object);const normal=hit.face.normal.clone();const axis=['x','y','z'].find(a=>Math.abs(normal[a])>.9);if(!axis)return;const sign=Math.sign(normal[axis]),worldNormal=normal.clone().transformDirection(hit.object.matrixWorld),rect=renderer.domElement.getBoundingClientRect();const a=hit.point.clone().project(camera),b=hit.point.clone().add(worldNormal).project(camera);const dx=(b.x-a.x)*rect.width/2,dy=-(b.y-a.y)*rect.height/2,len=Math.hypot(dx,dy);start={pointer:e.pointerId,before:snapshot(),axis,sign,originX:e.clientX,originY:e.clientY,directionX:len>4?dx/len:0,directionY:len>4?dy/len:-1,pixelsPerUnit:len>4?len:Math.max(10,rect.height/15),position:selected.position.clone(),scale:selected.scale.clone(),quaternion:selected.quaternion.clone()};renderer.domElement.setPointerCapture(e.pointerId)}else if(tool==='cut-face'){const hit=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked&&['box','mesh'].includes(o.userData.type)),false)[0];if(!hit)return;const normal=hit.face.normal.clone(),axis=['x','y','z'].find(a=>Math.abs(normal[a])>.999);if(!axis){document.querySelector('#status-text').textContent='Escolha uma face plana alinhada aos eixos locais.';return}select(hit.object);const sign=Math.sign(normal[axis]),worldNormal=normal.clone().transformDirection(hit.object.matrixWorld),local=hit.object.worldToLocal(hit.point.clone()).multiply(hit.object.scale),axes=['x','y','z'].filter(a=>a!==axis),first=axes.map(a=>local[a]);clearCutOutline();start={pointer:e.pointerId,object:hit.object,axis,sign,face:local[axis],first,second:[...first],cutPlane:new THREE.Plane().setFromNormalAndCoplanarPoint(worldNormal,hit.point)};drawCutOutline(start);renderer.domElement.setPointerCapture(e.pointerId)}else if(tool==='rectangle'){if(objects.length>=1000){alert('A cena suporta até 1000 objetos.');return}const p=point(e);if(!p)return;start={p,before:snapshot(),pointer:e.pointerId};preview=addBox(p.x,p.z,.0001,.0001,.0001);renderer.domElement.setPointerCapture(e.pointerId)}else if(tool==='extrude'){const hits=raycaster.intersectObjects(objects.filter(o=>o.visible&&!o.userData.locked),false);if(hits[0])select(hits[0].object);if(selected){start={y:e.clientY,height:selected.scale.y,center:selected.position.y,before:snapshot(),pointer:e.pointerId};renderer.domElement.setPointerCapture(e.pointerId)}}});
renderer.domElement.addEventListener('pointermove',e=>{if(tool==='measure'&&measureStart&&!measureComplete){const p=point(e);if(p){p.x=quantize(p.x);p.z=quantize(p.z);updateMeasurement(p)}return}if(!start||e.pointerId!==start.pointer)return;if(tool==='cut-face'){updateCutDrag(e);return}if(tool==='face'&&selected){const delta=((e.clientX-start.originX)*start.directionX+(e.clientY-start.originY)*start.directionY)/start.pixelsPerUnit;const result=resizeBoxFace({position:start.position,scale:start.scale,quaternion:start.quaternion,axis:start.axis,sign:start.sign,distance:snap?quantize(delta):delta});selected.position.copy(result.position);selected.scale.copy(result.scale)}else if(tool==='move'&&selected){const p=point(e);if(!p)return;selected.position.x=quantize(start.x+p.x-start.p.x);selected.position.z=quantize(start.z+p.z-start.p.z)}else if(tool==='rectangle'&&preview){const p=point(e);if(!p)return;const x=quantize(p.x),z=quantize(p.z),sx=quantize(start.p.x),sz=quantize(start.p.z);preview.scale.x=Math.max(.0001,Math.abs(x-sx));preview.scale.z=Math.max(.0001,Math.abs(z-sz));preview.position.x=(x+sx)/2;preview.position.z=(z+sz)/2}else if(tool==='extrude'&&selected){selected.scale.y=Math.max(.0001,quantize(start.height+(start.y-e.clientY)*.025));selected.position.y=start.center+(selected.scale.y-start.height)/2}});
function finishGesture(cancelled=false){if(!start)return;if(tool==='cut-face'){const draft=start;start=null;if(cancelled||Math.abs(draft.first[0]-draft.second[0])<.001||Math.abs(draft.first[1]-draft.second[1])<.001){clearCutOutline();document.querySelector('#status-text').textContent='Corte cancelado: desenhe um retângulo maior.';return}cutDraft=draft;document.querySelector('#cut-unit').textContent=projectUnit;document.querySelector('#cut-mode').value='pocket';document.querySelector('#cut-depth').disabled=false;document.querySelector('#cut-depth').value=formatLength(Math.min(draft.object.scale[draft.axis]/4,.5),projectUnit);document.querySelector('#cut-error').textContent='';document.querySelector('#cut-inline').hidden=false;document.querySelector('#cut-slider').max=String(toDisplay(draft.object.scale[draft.axis],projectUnit));document.querySelector('#cut-slider').min=String(toDisplay(.0001,projectUnit));updateCutPreview();document.querySelector('#cut-inline').scrollIntoView?.({block:'nearest'});return}const before=start.before;if(cancelled||(preview&&(preview.scale.x<.0001||preview.scale.z<.0001))){restore(before)}else if(JSON.stringify(before)!==JSON.stringify(snapshot())){history.push(before);if(history.length>50)history.shift();future=[];updateUndo();persist()}start=null;preview=null;renderPanel()}
renderer.domElement.addEventListener('pointerup',e=>{if(start&&e.pointerId===start.pointer)finishGesture()});
renderer.domElement.addEventListener('pointercancel',e=>{if(start&&e.pointerId===start.pointer)finishGesture(true)});
function toggleProjection(){if(transform.dragging||start)return;const aspect=container.clientWidth/(container.clientHeight||1)||1;camera=switchProjection(camera,controls.target,aspect);controls.object=camera;transform.camera=camera;controls.update();const isOrtho=camera.isOrthographicCamera;document.querySelector('#projection-label').textContent=isOrtho?'ORTOGRÁFICA':'PERSPECTIVA';const button=document.querySelector('#projection-toggle');button.setAttribute('aria-pressed',String(isOrtho));button.title=isOrtho?'Alternar para perspectiva (5 ou Num 5)':'Alternar para ortográfica (5 ou Num 5)';button.lastChild.textContent=isOrtho?' Perspectiva':' Ortográfica';}
document.querySelector('#projection-toggle').onclick=toggleProjection;
function presetView(view){const distance=Math.max(camera.position.distanceTo(controls.target),2);const directions={front:new THREE.Vector3(0,0,1),side:new THREE.Vector3(1,0,0),top:new THREE.Vector3(0,1,0.0001),back:new THREE.Vector3(0,0,-1),left:new THREE.Vector3(-1,0,0),bottom:new THREE.Vector3(0,-1,0.0001)};camera.position.copy(controls.target).addScaledVector(directions[view].normalize(),distance);controls.update()}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>presetView(button.dataset.view));
function frameObjects(items){if(!items.length)return;const bounds=new THREE.Box3();items.forEach(o=>bounds.union(new THREE.Box3().setFromObject(o)));const center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());const radius=Math.max(size.x,size.y,size.z,0.1);const aspect=container.clientWidth/(container.clientHeight||1)||1;const direction=camera.position.clone().sub(controls.target).normalize();if(!direction.lengthSq())direction.set(1,1,1).normalize();const orbitDistance=Math.max(camera.position.distanceTo(controls.target),2);controls.target.copy(center);if(camera.isOrthographicCamera){const distance=orbitDistance;camera.position.copy(center).addScaledVector(direction,distance);camera.zoom=camera.userData.viewHeight/(radius*Math.max(1.8,1.8/aspect));camera.updateProjectionMatrix()}else camera.position.copy(center).addScaledVector(direction,radius/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*Math.max(1.8,1.8/aspect));controls.update()}
function focusSelection(){if(selected)frameObjects([selected])}
document.querySelector('#frame-all').onclick=()=>frameObjects(objects.filter(o=>o.visible));
document.querySelector('#focus-view').onclick=focusSelection;
function home(){camera.position.set(8,7,9);controls.target.set(0,.5,0);if(camera.isOrthographicCamera){camera.zoom=camera.userData.viewHeight/(2*camera.position.distanceTo(controls.target)*Math.tan(THREE.MathUtils.degToRad(20)));camera.updateProjectionMatrix()}controls.update()}document.querySelector('#home-view').onclick=home;document.querySelector('#reset').onclick=()=>{if(!confirm('Restaurar a cena inicial? Os objetos atuais serão removidos.'))return;remember();clearObjects();applyEnvironment(defaultEnvironment());serial=1;projectName='Projeto sem título';document.querySelector('#project-name').value=projectName;addBox(0,0,2,2,2,'Cubo');persist();home();setTool('select')};
document.addEventListener('pointerdown',e=>{if(cutDraft&&!e.target.closest('#cut-inline')&&!e.target.closest('#viewport')){clearCutOutline();if(tool==='cut-face')setTool('select')}if(bevelSession&&!e.target.closest('#bevel-inline')&&!e.target.closest('#viewport')){closeBevel();if(tool==='bevel-edge')setTool('select')}},true);
window.addEventListener('keydown',e=>{
  if(!document.querySelector('#start-screen').hidden||arrayDialog.open||environmentDialog.open||alignDialog.open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||e.isComposing)return;
  const key=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;
  if((bevelSession||cutDraft)&&e.key!=='Escape'){closeBevel();clearCutOutline();setTool('select')}
  if(transform.dragging){if(e.key==='Escape')transform.reset();return}
  if(mod&&key==='c'&&selected){e.preventDefault();copyObject();return}
  if(mod&&key==='x'&&selected){e.preventDefault();cutObject();return}
  if(mod&&key==='v'&&clipboard){e.preventDefault();pasteObject();return}
  if(mod&&key==='s'){e.preventDefault();document.querySelector('#save-project').click();return}
  if(mod&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return}
  if(mod&&key==='y'){e.preventDefault();redo();return}
  if(mod&&!(e.ctrlKey&&['Numpad1','Numpad3','Numpad7'].includes(e.code)))return;
  if(e.code==='Numpad5'||e.code==='Digit5'||key==='5'){e.preventDefault();toggleProjection();return}
  if(e.code==='Numpad1'||e.code==='Numpad3'||e.code==='Numpad7'){e.preventDefault();presetView((e.ctrlKey?{Numpad1:'back',Numpad3:'left',Numpad7:'bottom'}:{Numpad1:'front',Numpad3:'side',Numpad7:'top'})[e.code]);return}
  if(e.shiftKey&&key==='h'){e.preventDefault();document.querySelector('#show-all').click();return}
  if(key==='h'&&selected){e.preventDefault();remember();selected.visible=false;select(null);persist();return}
  if(key==='home'){e.preventDefault();frameObjects(objects.filter(o=>o.visible));return}
  if(e.shiftKey&&key==='d'){e.preventDefault();duplicate();return}
  if(e.shiftKey&&key==='a'){e.preventDefault();addMenu.click();return}
  if(e.key==='Escape'){if(transform.dragging)transform.reset();if(start)finishGesture(true);dropdown.hidden=true;addDropdown.hidden=true;editDropdown.hidden=true;setTool('select');return}
  if(key==='m')setTool('measure');if(key==='1')setTool('gizmo-move');if(key==='2')setTool('gizmo-rotate');if(key==='3')setTool('gizmo-scale');if(key==='p')setTool('face');if(key==='v')setTool('select');if(key==='g')setTool('move');if(key==='r')setTool('rectangle');if(key==='e')setTool('extrude');if(key==='o')setTool('orbit');if(key==='f')focusSelection();
  if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected()}
});
function setProjectUnit(unit){projectUnit=isUnit(unit)?unit:'m';document.querySelector('#project-units').value=projectUnit;document.querySelector('#snap-step').value=formatLength(snapStep,projectUnit);document.querySelector('#snap-step').title='Passo do encaixe em '+projectUnit;}
document.querySelector('#project-units').onchange=e=>{const value=e.target.value;if(!isUnit(value)||value===projectUnit)return;remember();setProjectUnit(value);renderPanel();persist()};
function projectId(){return globalThis.crypto?.randomUUID?.()||`project-${Date.now()}-${Math.random().toString(36).slice(2)}`}
function showStart(){closeBevel();clearCutOutline();if(activeProjectId&&!persist())return;activeProjectId=null;try{sessionStorage.removeItem('bender-active-project')}catch{}document.querySelector('#start-screen').hidden=false;renderRecentProjects()}
function renderRecentProjects(){const list=document.querySelector('#recent-list');let items=[];try{items=readIndex(localStorage)}catch{}document.querySelector('#recents-count').textContent=items.length?`${items.length} projeto${items.length===1?'':'s'}`:'';list.innerHTML=items.length?items.map(item=>{const img=typeof item.thumbnail==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(item.thumbnail)&&item.thumbnail.length<200000?`<img src="${item.thumbnail}" alt="Prévia de ${escapeHtml(item.title)}">`:`<div class="recent-placeholder">${icon('box',27)}<span>Prévia disponível ao abrir</span></div>`;return `<article class="recent-card"><button class="recent-open" data-project="${item.id}" aria-label="Abrir ${escapeHtml(item.title)}">${img}<span class="recent-info"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.units||'m')} · ${new Date(item.updatedAt).toLocaleString('pt-BR')}</small></span></button><button class="recent-delete" data-delete-project="${item.id}" title="Excluir projeto" aria-label="Excluir ${escapeHtml(item.title)}">${icon('trash-2',15)}</button></article>`}).join(''):'<div class="recent-empty"><strong>Nenhum projeto recente</strong><span>Seu próximo projeto aparecerá aqui com uma prévia.</span></div>';list.querySelectorAll('[data-project]').forEach(button=>button.onclick=()=>openProject(button.dataset.project));list.querySelectorAll('[data-delete-project]').forEach(button=>button.onclick=()=>{if(!confirm('Excluir este projeto salvo neste navegador? Esta ação não pode ser desfeita.'))return;try{deleteProject(localStorage,button.dataset.deleteProject);renderRecentProjects()}catch{document.querySelector('#start-error').textContent='Não foi possível excluir o projeto.'}});createIcons({icons})}
function openProject(id){const data=loadProject(localStorage,id);if(!data){document.querySelector('#start-error').textContent='Não foi possível abrir este projeto. Ele pode estar corrompido.';return}try{restore(data);activeProjectId=id;sessionStorage.setItem('bender-active-project',id);history=[];future=[];clipboard=null;materialClipboard=null;proportionalScaling=false;updateUndo();home();setTool('select');document.querySelector('#start-screen').hidden=true;persist()}catch{document.querySelector('#start-error').textContent='Não foi possível abrir este projeto.'}}
document.querySelector('#open-start').onclick=showStart;
document.querySelector('#new-project-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#new-project-name').value.trim(),unit=document.querySelector('#new-project-unit').value;if(!name||!isUnit(unit))return;try{clearObjects();setProjectUnit(unit);applyEnvironment(defaultEnvironment());serial=1;projectName=name;document.querySelector('#project-name').value=name;addBox(0,0,2,2,2,'Cubo');const id=projectId();saveProject(localStorage,id,snapshot());activeProjectId=id;sessionStorage.setItem('bender-active-project',id);history=[];future=[];clipboard=null;materialClipboard=null;proportionalScaling=false;updateUndo();home();setTool('select');document.querySelector('#start-screen').hidden=true;persist()}catch{document.querySelector('#start-error').textContent='Não foi possível criar o projeto. Verifique o espaço de armazenamento do navegador.'}};
function initializeProjects(){try{const migrated=migrateLegacy(localStorage,projectId());if(migrated){const entry=readIndex(localStorage)[0],data=entry&&loadProject(localStorage,entry.id);if(data){restore(data);saveProject(localStorage,entry.id,data,captureThumbnail())}}const active=sessionStorage.getItem('bender-active-project');if(active&&loadProject(localStorage,active)){openProject(active);return}}catch{}showStart()}
function resize(){const w=container.clientWidth,h=container.clientHeight;if(!w||!h)return;resizeCamera(camera,w/h);renderer.setSize(w,h)}new ResizeObserver(resize).observe(container);addBox(0,0,2,2,2,'Cubo');updateUndo();setTool('select');resize();initializeProjects();function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}animate();
